export function createImportView(api) {
  const {$,$$,esc,nf,won,sum,getAnalysis,download,csvCell,rerender}=api;
  let kind='products',from='2026-01-01',to='2026-10-28',period='2026-07-01',query='',category='',sort='sales',page=0;
  const imported=()=>getAnalysis().importSources||[];
  function rows() {
    const original=getAnalysis(),a={...original,products:original.products.map(r=>api.catalog?.()?.row(r)||r),options:(original.options||[]).map(r=>api.catalog?.()?.row(r)||r)};
    return kind==='options'?(a.options||[]).filter(r=>r.start===period):a.products.filter(r=>r.date>=from&&r.date<=to);
  }
  function filtered(raw=rows()) {return raw.filter(r=>(!category||r.category===category)&&[r.name,r.category,r.option,r.originalName,r.originalCategory].join(' ').toLowerCase().includes(query.toLowerCase()))}
  function group(raw) {
    if(kind==='options')return raw;
    const map=new Map();
    for(const r of raw){const key=r.productId||JSON.stringify([r.category,r.name]);if(!map.has(key))map.set(key,{category:r.category,name:r.name,qty:0,sales:0,gross:0,discount:0,refund:0,refundQty:0,points:0,prepaid:0,days:new Set(),names:new Set(),categories:new Set()});const g=map.get(key);for(const k of ['qty','sales','gross','discount','refund','refundQty','points','prepaid'])g[k]+=r[k]||0;g.days.add(r.date);g.names.add(r.originalName||r.name);g.categories.add(r.originalCategory||r.category)}
    return [...map.values()];
  }
  function render(){
    const raw=rows(),items=filtered(raw),list=group(items).sort((a,b)=>(b[sort]||0)-(a[sort]||0));
    const categories=[...new Set(raw.map(r=>r.category))].sort();
    const coverage=getAnalysis().productCoverage.filter(d=>d>=from&&d<=to);
    page=Math.min(page,Math.max(0,Math.ceil(list.length/40)-1));
    const optionSources=imported().filter(r=>r.kind==='options');
    const partial=kind==='products'?getAnalysis().partialProductDates?.some(d=>d>=from&&d<=to):period==='2026-07-01';
    return `<div class="sales-brandline"><span class="brand-dot"></span>이코복스 이태원점 <span class="badge">상품·옵션 원본 반영</span></div>
    <div class="calendar-toolbar"><div class="segmented"><button data-import-kind="products" class="${kind==='products'?'selected':''}">상품별 판매</button><button data-import-kind="options" class="${kind==='options'?'selected':''}">옵션별 판매</button></div><a class="btn" href="#products?report=legacy">기존 베이커리·젤라또 리포트 ↗</a></div>
    ${kind==='products'?`<div class="calendar-filter"><span class="sub">연도 바로 보기</span>${[2025,2026].map(y=>`<button class="btn small ${from.startsWith(String(y))&&to.startsWith(String(y))?'primary':''}" data-import-year="${y}">${y}년</button>`).join('')}<a class="btn small" href="#dashboard?from=${from}&to=${to}&tab=products&compare=year">선택 상품 전년 비교 →</a><span class="sub">2025년 전체 · 2026년 10월 28일까지 상품 자료 확보</span></div>`:''}
    <section class="card"><div class="card-head"><div><h3>${kind==='products'?'상품 판매 분석':'옵션 선택 분석'}</h3><p class="sub">${kind==='products'?'동일 상품의 카테고리·한영 표기·HOT/ICED를 하나로 합산합니다.':'옵션은 제공된 원본 기간별로 조회합니다.'}</p></div><button class="btn small" id="downloadImport">↓ 조회 원본 CSV</button></div>
    <div class="detail-controls">${kind==='products'?`<div class="range-fields"><label>시작일<input type="date" id="importFrom" value="${from}" aria-label="상품 분석 시작일"></label><span>—</span><label>종료일<input type="date" id="importTo" value="${to}" aria-label="상품 분석 종료일"></label><button class="btn primary" id="applyImport">조회</button></div><a class="btn" href="#dashboard?from=${from}&to=${to}&tab=products">일·주·월 상세 분석 →</a>`:`<label>옵션 원본 기간<select id="optionPeriod" aria-label="옵션 원본 기간">${optionSources.map(s=>`<option value="${s.start}" ${s.start===period?'selected':''}>${s.start} ~ ${s.end}</option>`).join('')}</select></label>`}</div>
    <div class="note">${kind==='products'?`${coverage.length}일 자료 · POS에 기록된 상품 실매출 기준이며, 페이히어·오터·네이버 전체 상품을 합친 자료는 아닙니다. 배달앱 카테고리를 포함하며, 별도 채널 정산과 다시 합산하지 않습니다. 수량은 주문 건수와 다릅니다. 동일 상품은 채널·카테고리에 걸쳐 합산하고, 용량·세트 구성은 구분합니다. 환불은 원본 별도 열로 표시하며 실매출에서 임의로 재차 빼지 않습니다.`:'일자 정보가 없는 기간 누적 자료입니다. 일·주·월로 나누지 않으며, 옵션 매출을 상품 실매출에 더하지 않습니다. 총 주문 건수와 선택 비율은 원본 각 행의 값이며, 같은 상품명이 여러 행에 나타나도 임의로 합치지 않습니다.'}${partial?'<br><b>10월 28일 자료는 영업 중 추출한 잠정 집계입니다.</b>':''}</div></section>
    <div class="kpis" style="margin:20px 0">${(kind==='products'?[['상품 실매출',won(sum(items,'sales'))],['판매 수량',nf(sum(items,'qty'))+'개'],['할인 금액',won(sum(items,'discount'))],['환불 금액 · 별도 표시',won(sum(items,'refund'))]]:[['옵션 매출',won(sum(items,'sales'))],['옵션 선택 건수',nf(sum(items,'selections'))+'건'],['조회 원본 행',nf(items.length)+'행'],['일자별 분석','기간 누적 자료']]).map(([label,value])=>`<div class="card kpi"><div class="kpi-top">${label}</div><div class="kpi-value" style="font-size:24px">${value}</div><div class="kpi-foot">${query||category?'검색·필터 적용':'선택 기간 전체'}</div></div>`).join('')}</div>
    <section class="card"><div class="card-head"><h3>${kind==='products'?'상품별 실적':'옵션 원본 내역'}</h3><span class="sub">${nf(list.length)}${kind==='products'?'개 상품':'행'}</span></div><div class="detail-controls"><input id="importSearch" aria-label="상품 옵션 검색" placeholder="상품·옵션·카테고리 검색" value="${esc(query)}"><select id="importCategory" aria-label="통합 카테고리"><option value="">전체 카테고리</option>${categories.map(c=>`<option ${category===c?'selected':''} value="${esc(c)}">${esc(c)}</option>`).join('')}</select><select id="importSort" aria-label="원본 정렬">${(kind==='products'?[['sales','실매출순'],['qty','수량순'],['discount','할인순'],['refund','환불순']]:[['sales','옵션 매출순'],['selections','옵션 선택 건수순']]).map(([k,t])=>`<option value="${k}" ${sort===k?'selected':''}>${t}</option>`).join('')}</select></div>
    <div class="table-wrap"><table><thead><tr>${(kind==='products'?['상품 / 통합 카테고리','실매출','수량','총 매출','할인','환불 금액 / 수량','포인트 / 선불권']:['옵션 / 상품 / 카테고리','판매가','총 주문 건수','옵션 선택 건수','옵션 매출','평균 판매가','선택 비율 / 원본 행']).map((t,i)=>`<th class="${i?'num':''}">${t}</th>`).join('')}</tr></thead><tbody>${list.slice(page*40,page*40+40).map(r=>kind==='products'?`<tr><td><strong>${esc(r.name)}</strong><small class="table-sub">${esc(r.category)} · 관측 ${r.days.size}일</small>${r.names.size>1||r.categories.size>1?`<details class="product-aliases"><summary>통합 원본명 ${r.names.size}개 · 카테고리 ${r.categories.size}개</summary>${[...r.names].map(n=>`<div>${esc(n)}</div>`).join('')}<small>원본 카테고리: ${esc([...r.categories].join(', '))}</small></details>`:''}</td><td class="num"><strong>${won(r.sales)}</strong></td><td class="num">${nf(r.qty)}</td><td class="num">${won(r.gross)}</td><td class="num">${won(r.discount)}</td><td class="num">${won(r.refund)}<small class="table-sub">${nf(r.refundQty)}개</small></td><td class="num">${won(r.points)} / ${won(r.prepaid)}</td></tr>`:`<tr><td><strong>${esc(r.option)}</strong><small class="table-sub">${esc(r.name)}<br>${esc(r.category)}</small></td><td class="num">${won(r.unitPrice)}</td><td class="num">${nf(r.orderCount)}</td><td class="num">${nf(r.selections)}</td><td class="num">${won(r.sales)}</td><td class="num">${won(r.averagePrice)}</td><td class="num">${esc(r.selectionRate)}<small class="table-sub">엑셀 ${r.sourceRow}행</small></td></tr>`).join('')||'<tr><td colspan="7" class="empty">선택 조건에 자료가 없습니다.</td></tr>'}</tbody></table></div><div class="pagination"><span>${page+1} / ${Math.max(1,Math.ceil(list.length/40))} 페이지</span><div><button class="btn small" id="importPrev" ${page===0?'disabled':''}>이전</button><button class="btn small" id="importNext" ${page>=Math.ceil(list.length/40)-1?'disabled':''}>다음</button></div></div></section>
    <details class="card" style="margin-top:20px"><summary>반영한 파일 ${imported().length}개 · 합계 검증과 집계 기준</summary><div class="table-wrap"><table><thead><tr><th>원본</th><th class="num">반영 행</th><th>제공 범위 / 검증</th></tr></thead><tbody>${imported().map(s=>`<tr><td>${esc(s.label)}</td><td class="num">${nf(s.records)}</td><td>${s.start} ~ ${s.end}<small class="table-sub">${s.kind==='products'?'일별 상품 합계와 원본 일자별 합계 일치 · 전체 합계 대조 완료':'누적 옵션 원본 행 전체 보존'}</small></td></tr>`).join('')}</tbody></table></div><p class="sub">원본 카테고리·상품명·금액은 보존하고, 분석 화면에서만 통합 상품 기준을 적용합니다. 통합 원본명은 상품별로 펼쳐 확인할 수 있습니다. 일자에 귀속되지 않은 2026년 상반기 부분 분할결제 수량 5개·총 매출 300원·할인 300원·실매출 0원·환불 22,600원은 별도 보존하며 특정 날짜나 상품에 배분하지 않습니다. 상품 상세 합계와 원본 전체 합계의 차이는 이 별도 행입니다. 기존 총매출 달력은 기존 기준을 유지하고 POS 상품 범위에서 이번 자료를 조회합니다.</p><button class="btn small" id="downloadAdjustments">↓ 부분 분할결제 원본 CSV</button></details>`;
  }
  function exportCSV(name,rs,fields){download(name,'\uFEFF'+[fields.map(x=>x[1]),...rs.map(r=>fields.map(([k])=>(k==='name'?(r.originalName??r.name):k==='category'?(r.originalCategory??r.category):r[k])??''))].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
  function bind(){const on=(id,fn)=>{const el=$('#'+id);if(el)el.onclick=fn};
    $$('[data-import-year]').forEach(b=>b.onclick=()=>{const year=b.dataset.importYear,dates=getAnalysis().productCoverage.filter(d=>d.startsWith(year)).sort();from=dates[0];to=dates.at(-1);query='';category='';page=0;rerender()});
    $$('[data-import-kind]').forEach(b=>b.onclick=()=>{kind=b.dataset.importKind;category='';query='';sort='sales';page=0;rerender()});
    on('applyImport',()=>{const a=$('#importFrom').value,b=$('#importTo').value;if(!a||!b||a>b)return api.toast('시작일과 종료일을 확인하세요.');from=a;to=b;category='';page=0;rerender()});
    if($('#optionPeriod'))$('#optionPeriod').onchange=e=>{period=e.target.value;category='';page=0;rerender()};
    if($('#importCategory'))$('#importCategory').onchange=e=>{category=e.target.value;page=0;rerender()};
    if($('#importSort'))$('#importSort').onchange=e=>{sort=e.target.value;page=0;rerender()};
    if($('#importSearch'))$('#importSearch').oninput=e=>{query=e.target.value;page=0;rerender();$('#importSearch').focus();$('#importSearch').setSelectionRange(query.length,query.length)};
    on('importPrev',()=>{page--;rerender()});on('importNext',()=>{page++;rerender()});
    on('downloadImport',()=>exportCSV(`이코복스_${kind}_원본.csv`,filtered(),kind==='options'?[['store','매장명'],['start','시작일'],['end','종료일'],['option','옵션명'],['category','카테고리명'],['name','상품명'],['unitPrice','판매가'],['orderCount','총 주문 건수'],['selections','옵션 선택 건수'],['sales','옵션 총 매출액'],['averagePrice','옵션 평균 판매가'],['selectionRate','옵션 선택 비율'],['sourceRow','원본 행']]:[['date','영업일'],['category','카테고리명'],['name','상품명'],['unitPrice','상품별 단가'],['qty','수량'],['sold','판매량'],['gross','총 매출'],['sales','실매출'],['discount','할인'],['points','포인트 사용'],['prepaid','선불권 사용'],['refund','환불 금액'],['refundQty','환불 수량'],['sourceRow','원본 행']]));
    on('downloadAdjustments',()=>exportCSV('이코복스_부분분할결제.csv',(getAnalysis().productAdjustments||[]).map(r=>({...r,start:imported().find(s=>s.id===r.source)?.start,end:imported().find(s=>s.id===r.source)?.end})),[['start','시작일'],['end','종료일'],['label','구분'],['qty','수량'],['gross','총 매출'],['sales','실매출'],['discount','할인'],['refund','환불 금액'],['refundQty','환불 수량']]));
  }
  return {render,bind};
}
